output_text:
[
  {
    "id": "no_cart_in_single_file_shelf_aisles",
    "text": "Shopping carts are not allowed in single-file shelf aisles.",
    "abstraction": {
      "state_properties": {
        "single_file_shelf_aisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "single_file_shelf_aisle"
        ]
      }
    }
  },
  {
    "id": "no_enter_single_file_with_cart",
    "text": "An agent must not push a cart into a single-file aisle between shelves.",
    "abstraction": {
      "state_properties": {
        "single_file_between_shelves": {
          "and": [
            "adjShelf",
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "enter_single_file_with_cart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "single_file_between_shelves"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enter_single_file_with_cart"
    }
  },
  {
    "id": "park_cart_at_top_aisle_mouth",
    "text": "When arriving with a cart at the wide mouth of a single-file top shelf aisle, the agent is obliged to park the cart there before going in.",
    "abstraction": {
      "state_properties": {
        "top_aisle_mouth": {
          "and": [
            {
              "or": [
                "at(3,3)",
                "at(6,3)"
              ]
            },
            {
              "ge": [
                "freeWidthH",
                12
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "park_cart_at_mouth": {
          "pre": {
            "and": [
              "top_aisle_mouth",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": {
        "and": [
          "top_aisle_mouth",
          "hasCart"
        ]
      },
      "discharge": "park_cart_at_mouth"
    }
  },
  {
    "id": "retrieve_cart_after_cartless_single_file_pick",
    "text": "After collecting an item while cartless in a single-file shelf aisle, the agent must return and retrieve the parked cart.",
    "abstraction": {
      "state_properties": {
        "single_file_shelf_aisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "cartless_pick_in_single_file": {
          "pre": {
            "and": [
              "single_file_shelf_aisle",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "retrieve_cart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cartless_pick_in_single_file",
      "discharge": "retrieve_cart"
    }
  },
  {
    "id": "cart_required_for_lateral_side_bays",
    "text": "Items reached from narrow lateral side bays must be collected with the cart present.",
    "abstraction": {
      "state_properties": {
        "narrow_lateral_side_bay": {
          "and": [
            "adjShelf",
            {
              "or": [
                "shelfE",
                "shelfW"
              ]
            },
            {
              "le": [
                "freeWidthH",
                2
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "narrow_lateral_side_bay",
          "INTERACT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "avoid_cart_stops_in_lateral_side_bays",
    "text": "A cart should not be stopped for shelf interaction in a narrow lateral side bay; use a wider aisle face instead.",
    "abstraction": {
      "state_properties": {
        "narrow_lateral_side_bay": {
          "and": [
            "adjShelf",
            {
              "or": [
                "shelfE",
                "shelfW"
              ]
            },
            {
              "le": [
                "freeWidthH",
                2
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "narrow_lateral_side_bay",
          "hasCart",
          "INTERACT"
        ]
      }
    }
  },
  {
    "id": "avoid_short_vertical_shelf_faces_with_cart",
    "text": "Agents with carts should not collect from shelf faces located in short vertical pinch-points.",
    "abstraction": {
      "state_properties": {
        "short_vertical_shelf_face": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthV",
                2
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "short_vertical_shelf_face",
          "hasCart",
          "INTERACT"
        ]
      }
    }
  },
  {
    "id": "one_way_wide_aisles_no_west_with_cart",
    "text": "Wide horizontal aisles are one-way for carts, so carts may not be pushed west along them.",
    "abstraction": {
      "state_properties": {
        "wide_horizontal_aisle": {
          "ge": [
            "freeWidthH",
            12
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "wide_horizontal_aisle",
          "hasCart",
          "W"
        ]
      }
    }
  }
]
